def extract_python_chunks(path, source):
    """
    Extract focused, code-aware chunks from Python files.
    """

    chunks = []

    try:
        tree = ast.parse(source)
    except SyntaxError:
        return chunks

    # --------------------------------------------------
    # Module documentation
    # --------------------------------------------------

    module_doc = ast.get_docstring(tree)

    if module_doc:
        chunks.append(
            {
                "type": "module",
                "name": "module",
                "text": (
                    f"FILE: {path}\n"
                    f"MODULE DOCSTRING:\n{module_doc}"
                ),
            }
        )

    # --------------------------------------------------
    # Imports
    # --------------------------------------------------

    imports = []

    for node in tree.body:

        if isinstance(node, ast.Import):

            for alias in node.names:
                imports.append(alias.name)

        elif isinstance(node, ast.ImportFrom):

            module = node.module or ""

            for alias in node.names:
                imports.append(
                    f"{module}.{alias.name}"
                )

    if imports:
        chunks.append(
            {
                "type": "imports",
                "name": "imports",
                "text": (
                    f"FILE: {path}\n"
                    f"IMPORTS:\n"
                    + "\n".join(
                        f"- {item}"
                        for item in imports
                    )
                ),
            }
        )

    # --------------------------------------------------
    # Classes
    # --------------------------------------------------

    for node in ast.walk(tree):

        if isinstance(node, ast.ClassDef):

            methods = []

            for child in node.body:

                if isinstance(
                    child,
                    (ast.FunctionDef, ast.AsyncFunctionDef),
                ):
                    methods.append(
                        child.name
                    )

            doc = ast.get_docstring(node)

            text = (
                f"FILE: {path}\n"
                f"CLASS: {node.name}\n"
            )

            if doc:
                text += (
                    f"DESCRIPTION:\n{doc}\n"
                )

            if methods:
                text += (
                    "METHODS:\n"
                    + "\n".join(
                        f"- {method}"
                        for method in methods
                    )
                )

            chunks.append(
                {
                    "type": "class",
                    "name": node.name,
                    "text": text,
                }
            )

            # --------------------------------------------------
            # Individual methods
            # --------------------------------------------------

            for child in node.body:

                if isinstance(
                    child,
                    (ast.FunctionDef, ast.AsyncFunctionDef),
                ):

                    try:
                        method_source = ast.get_source_segment(
                            source,
                            child,
                        )
                    except Exception:
                        method_source = None

                    if not method_source:
                        continue

                    chunks.append(
                        {
                            "type": "method",
                            "name": (
                                f"{node.name}.{child.name}"
                            ),
                            "text": (
                                f"FILE: {path}\n"
                                f"CLASS: {node.name}\n"
                                f"METHOD: {child.name}\n"
                                f"SOURCE CODE:\n"
                                f"{method_source}"
                            ),
                        }
                    )

    # --------------------------------------------------
    # Top-level functions
    # --------------------------------------------------

    for node in tree.body:

        if isinstance(
            node,
            (ast.FunctionDef, ast.AsyncFunctionDef),
        ):

            try:
                function_source = ast.get_source_segment(
                    source,
                    node,
                )
            except Exception:
                function_source = None

            if not function_source:
                continue

            chunks.append(
                {
                    "type": "function",
                    "name": node.name,
                    "text": (
                        f"FILE: {path}\n"
                        f"FUNCTION: {node.name}\n"
                        f"SOURCE CODE:\n"
                        f"{function_source}"
                    ),
                }
            )

    # --------------------------------------------------
    # FastAPI endpoints
    # --------------------------------------------------

    endpoint_pattern = re.compile(
        r'@app\.(get|post|put|delete|patch)\(\s*["\']([^"\']+)'
    )

    for match in endpoint_pattern.finditer(source):

        method = match.group(1).upper()
        route = match.group(2)

        chunks.append(
            {
                "type": "endpoint",
                "name": f"{method} {route}",
                "text": (
                    f"FILE: {path}\n"
                    f"FASTAPI ENDPOINT:\n"
                    f"{method} {route}"
                ),
            }
        )

    return chunks

