def extract_text_chunks(path, source):

    chunks = []

    lines = source.splitlines()

    # Headings
    headings = []

    for line in lines:

        if re.match(r"^\s{0,3}#{1,6}\s+", line):

            heading = re.sub(
                r"^\s{0,3}#{1,6}\s+",
                "",
                line,
            ).strip()

            headings.append(heading)

    for heading in headings:

        chunks.append(
            {
                "type": "heading",
                "name": heading,
                "text": (
                    f"FILE: {path}\n"
                    f"SECTION: {heading}"
                ),
            }
        )

    # Bounded full-text chunks
    chunk_size = 1200

    for start in range(
        0,
        len(lines),
        40,
    ):

        block = "\n".join(
            lines[start:start + 40]
        ).strip()

        if not block:
            continue

        chunks.append(
            {
                "type": "text",
                "name": f"lines_{start + 1}",
                "text": (
                    f"FILE: {path}\n"
                    f"TEXT:\n{block}"
                ),
            }
        )

    return chunks

