def chunk_relevance(item, query):
    """
    Give a small boost to chunk types that are directly
    relevant to the user's question.
    """

    q = query.lower()
    chunk_type = item.get("type", "").lower()
    name = item.get("name", "").lower()

    score = 0.0

    # Endpoint questions
    if any(
        word in q
        for word in [
            "endpoint",
            "api",
            "route",
            "routes",
        ]
    ):
        if chunk_type == "endpoint":
            score += 10

    # Method questions
    if any(
        word in q
        for word in [
            "method",
            "methods",
        ]
    ):
        if chunk_type == "method":
            score += 10

        if chunk_type == "class":
            score += 5

    # Function questions
    if any(
        word in q
        for word in [
            "function",
            "functions",
        ]
    ):
        if chunk_type == "function":
            score += 10

    # Class questions
    if any(
        word in q
        for word in [
            "class",
            "classes",
        ]
    ):
        if chunk_type == "class":
            score += 10

    # General "what does it do?" questions
    if any(
        phrase in q
        for phrase in [
            "what does",
            "what is",
            "purpose",
            "explain",
            "describe",
        ]
    ):
        if chunk_type == "module":
            score += 5

        if chunk_type in {
            "class",
            "function",
            "method",
        }:
            score += 2

    # Name match
    if name and name in q:
        score += 3

    return score

